tools observations sql --query "SELECT o.ts, o.obs_type, length(p.body) AS n FROM observations o JOIN phone_messages p ON p.observation_id=o.id WHERE o.ts >= '2026-10-04T19:47:30+05:30' AND o.ts <= '2026-10-04T19:49:30+05:30' ORDER BY o.ts DESC LIMIT 10" 2>&1 | head -20; tools observations sql --query "SELECT e.ts, length(e.text) n FROM chat_events e WHERE e.agent_id = (SELECT agent_id FROM chats WHERE external_id = 'chat-sessions/chat-01M42BRM3XS8YSRFDXMGYQEEH9/chat') AND e.ts >= '2026-10-04T19:47:30+05:30' ORDER BY e.ts DESC LIMIT 5" 2>&1 | head
